export type AutomationScenarioInputAutoApproveKindItem = "sale" | "purchase" | "bank_receipt" | "bank_payment" | "counterparty" | "contract" | "inventory_writeoff" | "cash_order_in" | "cash_order_out" | "advance_report";

/** Когда запускать: по событию хука, по расписанию, по событию внутри Tungo или только вручную. Вид — в kind. */
