  /** Имя файла — попадёт в название задания */
  file_name?: string;
  /** Сколько строк взять в работу (1–2000); без него — все */
  limit?: number;
  /** Содержимое выписки в формате 1CClientBankExchange («выгрузка для 1С» из интернет-банка) текстом, до 8 МБ */
