export type CompanyAutonomyLevelsCashOrderIn = "L1" | "L2" | "L3";

/** `L1` — ИИ только готовит, записывает человек; `L2` — автоодобрение пишет черновиком; `L3` — пишет и проводит */
export type CompanyAutonomyLevelsCashOrderOut = "L1" | "L2" | "L3";

/** `L1` — ИИ только готовит, записывает человек; `L2` — автоодобрение пишет черновиком; `L3` — пишет и проводит */
export type CompanyAutonomyLevelsContract = "L1" | "L2" | "L3";

/** `L1` — ИИ только готовит, записывает человек; `L2` — автоодобрение пишет черновиком; `L3` — пишет и проводит */
export type CompanyAutonomyLevelsCounterparty = "L1" | "L2" | "L3";

/** `L1` — ИИ только готовит, записывает человек; `L2` — автоодобрение пишет черновиком; `L3` — пишет и проводит */
export type CompanyAutonomyLevelsInventoryWriteoff = "L1" | "L2" | "L3";

/** `L1` — ИИ только готовит, записывает человек; `L2` — автоодобрение пишет черновиком; `L3` — пишет и проводит */
export type CompanyAutonomyLevelsPurchase = "L1" | "L2" | "L3";

/** `L1` — ИИ только готовит, записывает человек; `L2` — автоодобрение пишет черновиком; `L3` — пишет и проводит */
export type CompanyAutonomyLevelsSale = "L1" | "L2" | "L3";

/** Бейджи компании в общем списке — только по предложениям ИИ. Карточки журнала (выписка дня, проверка учёта, вопросы агента) сюда не входят: точные числа разделов — counts в GET /v1/companies/{co}/feed */
export interface CompanyCounts {
  /** Предложений с вопросом ИИ к человеку (раздел ленты «Вопросы от ИИ»: нужен ответ, чтобы продолжить) */
  proposals_blocked: number;
  /** Предложений ИИ ждут решения человека (раздел ленты «Требует решения»: подготовлено, одобрено, но не записано, не записалось) */
  proposals_to_decide: number;
}

/** Форма: ip — ИП, too — ТОО, ao — АО, other — другое */
export type CompanyLegalForm = "ip" | "too" | "ao" | "other";

/** Компания в общем списке — с бейджами (counts) */
export interface CompanyListItem {
  /** БИН или ИИН, 12 цифр; null — ещё не указан */
  bin: string | null;
  counts: CompanyCounts;
  /** Когда компанию завели. ISO 8601 в UTC (…Z); показывать по времени Казахстана — Asia/Almaty (UTC+5), а не по поясу браузера */
  created_at: string;
  /** Компания — её id во всех адресах /v1/companies/{co}/… (co_…) */
  id: string;
  legal_form: CompanyLegalForm;
  /** Название компании, как его ввели при заведении */
  name: string;
  /** Ваши права в этой компании — по ним кабинет прячет или гасит кнопки (нет proposals.approve — нет «Одобрить»). По ключу API — права, суженные до прав ключа. Порядок — как в каталоге прав */
  permissions: CompanyPermission[];
  /** Ваша роль в компании (ключ роли: owner, chief_accountant, accountant, viewer…). Пустая строка — вы не участник компании, а владелец/админ организации, который её правил или архивировал */
  role: string;
  /** Название вашей роли для показа */
  role_name: string;
  status: CompanyStatus;
  /** Организация, которой принадлежит компания (кто платит) (ws_…) */
  workspace_id: string;
}

/** Право в компании: - `company.read` — Видеть компанию и её данные - `company.manage` — Менять настройки компании - `company.members.manage` — Приглашать и убирать участников, менять роли - `onec.connect` — Подключать и на… */
export type CompanyPermission = "company.read" | "company.manage" | "company.members.manage" | "onec.connect" | "proposals.create" | "proposals.approve" | "chat.use" | "audit.read" | "automations.manage";

/** active — работает; suspended — приостановлена (запросы к ней — 403 company_suspended); archived — в архиве */
export type CompanyStatus = "active" | "suspended" | "archived";

/** Форма, которая ждёт этих данных */
export interface DataGapForm {
  /** Сколько ячеек формы ждёт этого */
  cells: number;
  /** Код формы (бланка), например 300.00 — декларация по НДС */
  form: string;
  /** Периоды, которые ждут этих данных */
  periods: TaxPeriodRef[];
  /** Название формы */
  title: string;
}

/** Состояние формы за период */
export interface DataGapFormStatus {
  /** Форма не посчиталась: почему (текст для человека) */
  error?: string;
  /** Код формы (бланка), например 300.00 — декларация по НДС */
  form: string;
  /** Начало периода — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  from: string;
  /** Раздел отчётности: tax, financial, statistics, certificate */
  group: string;
  /** Пунктов «чего не хватает» */
  missing: number;
  /** Ячеек не посчитано */
  not_computed: number;
  /** Код периода — его передавать в ?period=: 2026-Q2 — квартал, 2026-H1 — полугодие, 2026-06 — месяц (у форм «с начала года» — январь–июнь), 2026 — год */
  period: string;
  /** Период по-русски для показа */
  period_title: string;
  /** Название формы */
  title: string;
  /** Конец периода — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  to: string;
  /** Ячеек в 1С заполнено, а мы не считаем */
  uncovered: number;
}

/** Что заполнить: одна нехватка, общая для нескольких форм и периодов */
export interface DataGapItem {
  action: DataGapItemAction;
  /** Что сделать — по-русски для заголовка группы */
  action_title: string;
  /** Какие формы и периоды ждут этих данных */
  forms: DataGapForm[];
  /** id пункта (gap_1, gap_2…) — на него ссылается objects[].gap_ids */
  id: string;
  /** Объекты 1С, у которых не хватает */
  objects: FormOnecObject[];
  /** Чего не хватает */
  what: string;
  /** Где в 1С заполнить */
  where?: string;
  /** Зачем */
  why: string;
}

export type DataGapItemAction = Record<string, unknown>;

/** Объект 1С и его нехватки */
export interface DataGapObject {
  /** id пунктов из gaps, которые относятся к этому объекту */
  gap_ids: string[];
  /** Название объекта 1С */
  name: string;
  /** Ref_Key объекта в 1С */
  ref?: string;
}

/** Что заполнить в 1С, чтобы досчитались формы года */
export interface DataGaps {
  /** Состояние каждой формы за начавшиеся периоды года */
  forms: DataGapFormStatus[];
  /** Что заполнить — один список на все формы, по порядку действий: заполнить в 1С, закрыть месяц, перенести, ответить, нормы, ждать */
  gaps: DataGapItem[];
  /** Что делать дальше — текст для человека */
  next: string;
  /** Те же пункты по объектам 1С (у одного основного средства может быть несколько нехваток) */
  objects: DataGapObject[];
  /** Сколько пунктов по каждому действию */
  summary: DataGapsSummary;
  /** Год */
  year: number;
}

/** Сколько пунктов по каждому действию */
export interface DataGapsSummary {
  /** Сколько пунктов с action = answer */
  answer: number;
  /** Сколько пунктов с action = close_month */
  close_month: number;
  /** Сколько пунктов с action = fill_in_1c */
  fill_in_1c: number;
  /** Сколько пунктов с action = norm */
  norm: number;
  /** Сколько пунктов с action = other_source */
  other_source: number;
  /** Сколько пунктов с action = wait */
  wait: number;
}

/** Итог опроса DirectBank */
export interface DirectBankPollResult {
  /** Сколько предложений создано */
  created: number;
  /** Сколько документов банка получено */
  documents: number;
  /** id задания выписки дня (bat_…); null — новых документов в банке нет */
  job_id: string | null;
}

/** Куда вернуть клиента после формы ePay (только адреса нашего фронтенда). */
export interface EpayReturnLinks {
  /** Страница кабинета, куда ePay вернёт клиента после успеха. Только адрес нашего фронтенда, иначе 400 */
  back_link: string;
  /** Страница кабинета, куда вернуть после отказа или отмены. Только адрес нашего фронтенда */
  failure_back_link: string;
}

/** Тело любой ошибки API (статусы 4xx и 5xx): `{"type":"error","error":{"type":"…","code":"…","message":"…"},"request_id":"…"}`. Интерфейс ветвится по error.type и error.code, человеку показывает error.message и request_id. */
export interface Error {
  error: ErrorDetail;
  /** Номер запроса (тот же, что в заголовке x-request-id). Показывать мелко рядом с ошибкой с кнопкой «скопировать»: по нему поддержка находит запрос в журнале. null — номер не успел появиться (очень ранний отказ). */
  request_id: string | null;
  /** Всегда «error»: так тело ошибки отличается от обычного ответа. */
  type: "error";
}

/** Что пошло не так. Все 503 — с заголовком Retry-After (через сколько секунд повторить). Кроме описанных, у отдельных ручек бывают свои поля рядом с code (например status у wrong_status, state у wrong_state, reason у dialo… */
export interface ErrorDetail {
  /** При code = login_method_not_allowed — какими способами входа организация пускает к своим данным: email_otp — код из почты, google, apple, telegram, sso — SSO организации. Предложить выйти и войти одним из них. */
  allowed_methods?: ErrorDetailAllowedMethodItem[];
  /** Уточнение вида: по нему выбирается действие интерфейса (кнопка «Пополнить», «Войти иначе»…). Нет поля — хватает type и message. Известные коды: - `sso_domain_taken` (409) — домен SSO уже подтверждён другой организацией -… */
  code?: string;
  /** При code = validation_failed — ошибки по полям, в порядке проверки; у одного поля может быть несколько. */
  fields?: FieldError[];
  /** Готовый текст для человека по-русски: что случилось, что делать и к кому обратиться. Показывать как есть; не разбирать — формулировки меняются. */
  message: string;
  /** При code = missing_permission — какого права не хватает: права в компании (company.read, company.manage, company.members.manage, onec.connect, proposals.create, proposals.approve, chat.use, audit.read, automations.manage… */
  permission?: string;
  /** При code = role_above_yours — права этой роли, которых нет у того, кто выдаёт. Показать списком: «у роли есть права, которых нет у вас: …». */
  permissions?: string[];
  /** Когда ограничение снимется само — ISO 8601, UTC. Есть у plan_limit_reached (конец окна тарифа) и у месячных потолков (workspace_cap_reached, company_cap_reached, member_cap_reached, key_cap_reached, platform_cap_reached … */
  resets_at?: string;
  /** При code = role_above_yours — ключ роли в компании, которую нельзя выдать или снять (например chief_accountant). */
  role?: string;
  /** Вид ошибки — по нему ветвится клиент (не по тексту message). Статус HTTP у вида один, кроме invalid_request_error: - `invalid_request_error` (400) — запрос неверен: поле не прошло проверку, неверный формат, действие сейч… */
  type: ErrorDetailType;
}

export type ErrorDetailAllowedMethodItem = "email_otp" | "google" | "apple" | "telegram" | "sso";

/** Вид ошибки — по нему ветвится клиент (не по тексту message). Статус HTTP у вида один, кроме invalid_request_error: - `invalid_request_error` (400) — запрос неверен: поле не прошло проверку, неверный формат, действие сейч… */
export type ErrorDetailType = "invalid_request_error" | "authentication_error" | "payment_required_error" | "permission_error" | "not_found_error" | "conflict_error" | "gone_error" | "limit_error" | "api_error" | "unavailable_error";

/** Что делать с входящим ЭСФ: `document_found` — «Документ найден»; `propose_purchase` — «Предложить поступление»; `counterparty_needed` — «Нужен контрагент»; `ask_human` — «Спросить человека»; `skip` — «Пропустить». docume… */
export type EsfIncomingAction = "document_found" | "propose_purchase" | "counterparty_needed" | "ask_human" | "skip";

/** Входящий ЭСФ (от поставщика) и поступление в 1С под него */
export interface EsfIncomingItem {
  action: EsfIncomingAction;
  /** Подпись action для человека — показывать как есть */
  action_title: string;
  /** Что мешает завести поступление */
  blockers: string[];
  /** Дата ЭСФ — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  date: string;
  /** Регистрационный номер ЭСФ в ИС ЭСФ (или его id, если номера нет) */
  esf: string;
  match: EsfIncomingMatch;
  /** Номер ЭСФ у поставщика */
  number: string;
  /** Статус ЭСФ в ИС ЭСФ, как записан в 1С; null — неизвестен */
  status: string | null;
  /** Поставщик */
  supplier: string;
  /** БИН/ИИН поставщика, 12 цифр */
  supplier_bin: string;
  total: EsfIncomingItemTotal;
  /** Дата оборота (поставки) ГГГГ-ММ-ДД; null — не указана */
  turnover_date: string | null;
  vat: EsfIncomingItemVat;
  /** Предупреждения */
  warnings: string[];
}

export interface EsfIncomingItemTotal {
  /** Тенге десятичным числом, до тиына: 1234.5 = 1 234,50 ₸. Для показа и графиков; считать деньги — по amount_tiyn */
  amount: number;
  /** То же целым числом тиынов (1 ₸ = 100 тиын): 1234.5 ₸ = 123450. Складывать и сравнивать суммы — по этому полю */
  amount_tiyn: number;
  /** Готовая строка для человека — показывать как есть: «1 234,50 ₸» */
  formatted: string;
}

export interface EsfIncomingItemVat {
  /** Тенге десятичным числом, до тиына: 1234.5 = 1 234,50 ₸. Для показа и графиков; считать деньги — по amount_tiyn */
  amount: number;
  /** То же целым числом тиынов (1 ₸ = 100 тиын): 1234.5 ₸ = 123450. Складывать и сравнивать суммы — по этому полю */
  amount_tiyn: number;
  /** Готовая строка для человека — показывать как есть: «1 234,50 ₸» */
  formatted: string;
}

/** Нашлось ли поступление в 1С под этот ЭСФ */
export interface EsfIncomingMatch {
  /** Сколько похожих документов — когда однозначного нет */
  candidates?: number;
  /** Найденное (или уже привязанное) поступление в 1С */
  document?: EsfIncomingMatchDocument;
  /** true — ЭСФ уже привязан к документу в 1С */
  linked?: "true";
  /** matched — найдено поступление; ambiguous — подходит несколько (candidates); not_found — не найдено; counterparty_unknown — поставщика нет в 1С; no_documents — у поставщика нет документов */
  status: EsfIncomingMatchStatus;
}

/** Найденное (или уже привязанное) поступление в 1С */
export interface EsfIncomingMatchDocument {
  amount: EsfIncomingMatchDocumentAmount;
  /** Дата документа — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  date: string;
  /** Вид документа 1С без Document_ */
  kind: string;
  /** Номер документа */
  number: string;
}

export interface EsfIncomingMatchDocumentAmount {
  /** Тенге десятичным числом, до тиына: 1234.5 = 1 234,50 ₸. Для показа и графиков; считать деньги — по amount_tiyn */
  amount: number;
  /** То же целым числом тиынов (1 ₸ = 100 тиын): 1234.5 ₸ = 123450. Складывать и сравнивать суммы — по этому полю */
  amount_tiyn: number;
  /** Готовая строка для человека — показывать как есть: «1 234,50 ₸» */
  formatted: string;
}

/** matched — найдено поступление; ambiguous — подходит несколько (candidates); not_found — не найдено; counterparty_unknown — поставщика нет в 1С; no_documents — у поставщика нет документов */
export type EsfIncomingMatchStatus = "matched" | "ambiguous" | "not_found" | "counterparty_unknown" | "no_documents";

/** Входящие ЭСФ и поступления в 1С под них */
export interface EsfIncomingReport {
  /** На какую дату данные 1С — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  as_of: string;
  /** Входящие ЭСФ за окно, новые первыми — эта страница (не больше limit) */
  data: EsfIncomingItem[];
  /** Курсор следующей страницы: тот же запрос (с теми же фильтрами) и `?cursor=<это значение>`. null — страниц больше нет. Непрозрачный — не разбирать */
  next_cursor: string | null;
  /** Начало окна — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  since: string;
  /** Сколько строк всего под фильтр (на всех страницах) — для «показано N из M» */
  total: number;
  /** Конец окна включительно — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  until: string;
}

/** Реализация без действующего ЭСФ */
export interface EsfOutgoingItem {
  /** Сколько дней прошло с реализации (на дату as_of) */
  age_days?: number;
  /** Что мешает выписать ЭСФ — показать красным */
  blockers: string[];
  /** ЭСФ по реализации, если есть (нерабочий) */
  esf?: EsfOutgoingItemEsf;
  /** Что не так — развёрнуто для человека */
  problem: string;
  sale: EsfSale;
  /** Счёт-фактура в 1С по этой реализации, если есть */
  tax_invoice?: EsfOutgoingItemTaxInvoice;
  verdict: EsfVerdict;
  /** Подпись verdict для человека — показывать как есть */
  verdict_title: string;
  /** Предупреждения */
  warnings: string[];
}

/** ЭСФ по реализации, если есть (нерабочий) */
export interface EsfOutgoingItemEsf {
  /** Дата ЭСФ — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  date: string;
  /** Номер ЭСФ */
  number: string;
  /** Регистрационный номер ЭСФ в ИС ЭСФ */
  registration_number?: string;
  /** Состояние ЭСФ в 1С (Отозван, Аннулирован, ОтклоненПолучателем…) */
  state?: string;
  /** Статус ЭСФ в ИС ЭСФ, как записан в 1С */
  status?: string;
}

/** Счёт-фактура в 1С по этой реализации, если есть */
export interface EsfOutgoingItemTaxInvoice {
  /** Дата счёта-фактуры */
  date: string;
  /** Номер счёта-фактуры */
  number: string;
  /** Способ выставления (бумажный, электронный), как в 1С */
  way?: string;
}

/** Исходящие ЭСФ: реализации, по которым ЭСФ не выписан или не действует */
export interface EsfOutgoingReport {
  /** На какую дату данные 1С — ГГГГ-ММ-ДД, календарная дата без часового пояса: показывать как есть */
  as_of: string;
  /** Реализации без действующего ЭСФ — эта страница (не больше limit) */
  data: EsfOutgoingItem[];
  /** Курсор следующей страницы: тот же запрос (с теми же фильтрами) и `?cursor=<это значение>`. null — страниц больше нет. Непрозрачный — не разбирать */
  next_cursor: string | null;
  /** Оговорки разбора — текст для человека */
  note?: string;
  /** Сколько строк всего под фильтр (на всех страницах) — для «показано N из M» */
  total: number;
}

