  /** Каналы — id сценариев автоматизаций (scn_…, до 10). Заданы — на адрес приходят только события этих сценариев (automation.run.completed, automation.run.failed, automation.run.notice, automation.write_unknown), и никаких д… */
  channels?: string[] | null;
  /** Подпись адреса для людей (до 500 знаков) */
